CREATE TABLE IF NOT EXISTS official_documents (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,service_request_id VARCHAR(64) NOT NULL REFERENCES student_service_requests(id),serial_number VARCHAR(100) NOT NULL,kind VARCHAR(40) NOT NULL,title VARCHAR(200) NOT NULL,sha256_hex VARCHAR(64) NOT NULL,pdf_bytes BYTEA NOT NULL,verification_token_hash VARCHAR(64) NOT NULL,state VARCHAR(20) NOT NULL CHECK(state IN ('issued','revoked')),issued_by VARCHAR(64) NOT NULL,issued_at TIMESTAMP WITH TIME ZONE NOT NULL,revoked_by VARCHAR(64),revoked_at TIMESTAMP WITH TIME ZONE,revocation_reason VARCHAR(1000),CONSTRAINT uq_official_serial UNIQUE(institution_id,serial_number),CONSTRAINT uq_official_request UNIQUE(institution_id,service_request_id),CONSTRAINT uq_official_token UNIQUE(verification_token_hash));
CREATE INDEX IF NOT EXISTS ix_official_documents_institution_id ON official_documents(institution_id);
CREATE INDEX IF NOT EXISTS ix_official_documents_student_id ON official_documents(student_id);
CREATE INDEX IF NOT EXISTS ix_official_documents_verification_token_hash ON official_documents(verification_token_hash);
